// Carrega dados Context LoadWWPContext(&WWPContext) &prefCodigo = &WWPContext.prefCodigo
// Carrega dados do WizardData &WizardData.FromXml(FileXmlToWizardData(&WebSessionKey))
do 'GravaDadosRancho'
do 'GravaRemessa'
do 'GravaDistribuicao'
Sub 'GravaRemessa'
/* Registra remessa */ &dataInicial = &WizardData.Periodo.DataInicial &dataFinal = &WizardData.Periodo.DataFinal &remCodigo = PRCDGerarNovoCodigo('remessas')
New prefCodigo = &prefCodigo remCodigo = &remCodigo remStatus = Status.Ativo remCadastro = ServerDate() remAlteracao = ServerDate() remUsuario = &WWPContext.UserName +' | IP : ' + RemoteAddr() + ' | H:M:S : '+ Time() remGerSemana1Ini = &dataInicial remGerSemana1Fim = &dataFinal // remGerSemana2Ini // remGerSemana2Fim // remGerSemana3Ini // remGerSemana3Fim // remGerSemana4Ini // remGerSemana4Fim // remGerSemana5Ini // remGerSemana5Fim remRancho = true EndNew
// &trnsRemessas = new() // &trnsRemessas.remStatus = Status.Ativo // &trnsRemessas.remRancho = true // &trnsRemessas.remGerSemana1Ini = &dataInicial // &trnsRemessas.remGerSemana1Fim = &dataFinal // // &trnsRemessas.Insert() // if &trnsRemessas.Fail() // &IsSucess = false // &Messages = &trnsRemessas.GetMessages() // // log.Error(&Messages.ToJson(),'GeraDistribuicao.Rollback') // Rollback // Return // else // &IsSucess = true // &remCodigo = &trnsRemessas.remCodigo // Commit // endif
/* Registra atendimento da remessa */ for &PessoasGridItem in &WizardData.Pessoas2.Grid
/* Berçario 1 */ if &PessoasGridItem.Bercario1 > 0 &AreEnsCodigo = 1 &AreEnsSequencial = 1 &AreEnsTurno = turno.Int &locCodigo = &PessoasGridItem.locCodigo &remNormal = &PessoasGridItem.Bercario1 do 'GravaAtendimentoRemessa' endif
/* Berçario 2 */ if &PessoasGridItem.Bercario2 > 0 &AreEnsCodigo = 2 &AreEnsSequencial = 2 &AreEnsTurno = turno.Int &locCodigo = &PessoasGridItem.locCodigo &remNormal = &PessoasGridItem.Bercario2 do 'GravaAtendimentoRemessa' endif
/* Creche */ if &PessoasGridItem.Creche > 0 &AreEnsCodigo = 3 &AreEnsSequencial = 3 &AreEnsTurno = turno.Int &locCodigo = &PessoasGridItem.locCodigo &remNormal = &PessoasGridItem.Creche do 'GravaAtendimentoRemessa' endif
/* EMEB */ if &PessoasGridItem.Emeb > 0 &AreEnsCodigo = 4 &AreEnsSequencial = 4 &AreEnsTurno = turno.Int &locCodigo = &PessoasGridItem.locCodigo &remNormal = &PessoasGridItem.Emeb do 'GravaAtendimentoRemessa' endif
/* Integral */ if &PessoasGridItem.Integral > 0 &AreEnsCodigo = 5 &AreEnsSequencial = 5 &AreEnsTurno = turno.Int &locCodigo = &PessoasGridItem.locCodigo &remNormal = &PessoasGridItem.Integral do 'GravaAtendimentoRemessa' endif
endfor
EndSub
Sub 'GravaAtendimentoRemessa' New prefCodigo = &prefCodigo remCodigo = &remCodigo remAreEnsCodigo = &AreEnsCodigo remAreEnsSequencial = &AreEnsSequencial remAreEnsTurno = &AreEnsTurno remLocal = &locCodigo remNormal = &remNormal EndNew EndSub
Sub 'GravaDistribuicao'
&distDataEnvio = &WizardData.Periodo.DataEnvio &remTipoRemessa = &WizardData.Alimentos.prodCodigoTipoRemessa
/* Busca local de origem */ For each Where prefCodigo = &prefCodigo &distLocalOrigem = prefLocalDeposito When none &distLocalOrigem = 0 Endfor
&locCodigo = 0 for &GuiasGridItem in &WizardData.Guias.Grid if &locCodigo <> &GuiasGridItem.locCodigo &locCodigo = &GuiasGridItem.locCodigo &distObservacao = &GuiasGridItem.distObservacao // log.Info(&locCodigo.ToString(),'CabeçalhoDistribuicao') &distCodigo = PRCDSalvarCabecalhoDistribuicao(&prefCodigo,&remCodigo,&locCodigo,&distDataEnvio,&distLocalOrigem,&remTipoRemessa,&dataInicial,&dataFinal,&distObservacao) endif
&prodCodigo = &GuiasGridItem.prodCodigo &AreEnsCodigo = 0 &AreEnsSequencial = 0 &AreEnsTurno = turno.Int &Quantidade = &GuiasGridItem.Quantidade &PerCapta = 1 // log.Info(&distCodigo.ToString(),'ItemDistribuicao') PRCDSalvarRemessaAlimentos(&prefCodigo,&remCodigo,&prodCodigo,&AreEnsCodigo,&AreEnsSequencial,&AreEnsTurno,&Quantidade,&PerCapta,&distCodigo,&dataInicial,&dataFinal,0)
/* Atualiza estoque */ // log.Info(&prodCodigo.ToString(),'Estoque') PRCDEstoqueMovimentacao(&distCodigo,&prodCodigo,&distLocalOrigem,&Quantidade,'RD','N',0,&Retorno)
endfor
Endsub
Sub 'GravaDadosRancho'
&Rancho = new() &Rancho.prefCodigo = &prefCodigo &Rancho.RanchoAno = &WizardData.Periodo.DataEnvio.Year() &Rancho.RanchoMes = Meses.Convert(&WizardData.Periodo.DataEnvio.Month()) &Rancho.RanchoDataEnvio = &WizardData.Periodo.DataEnvio
/* Carrega dados da área de ensino */ &AreEnsCodigo = 1 // Berçario 1 do 'CarregaDadosAreaEnsino'
&AreEnsCodigo = 2 // Berçario 2 do 'CarregaDadosAreaEnsino'
&AreEnsCodigo = 3 // Creche do 'CarregaDadosAreaEnsino'
&AreEnsCodigo = 4 // EMEB do 'CarregaDadosAreaEnsino'
&AreEnsCodigo = 5 // Integral do 'CarregaDadosAreaEnsino'
&AreEnsCodigo = 99999997 // Funcionários do 'CarregaDadosAreaEnsino'
// log.Info(&Rancho.ToJson(),&Pgmname + '.Rancho')
/* Grava os dados */ &Rancho.InsertOrUpdate() if &Rancho.Fail() &IsSucess = false &Messages = &Rancho.GetMessages() // log.Error(&Messages.ToJson(),'GravaDadosRancho.Rollback') Rollback Return else &IsSucess = true Commit endif
Endsub
Sub 'CarregaDadosAreaEnsino'
&RanchoAreasEnsino = new() &RanchoAreasEnsino.RanchoAreasEnsinoCodigo = &AreEnsCodigo
/* Quantidade de pessoas atendidas */ for &PessoasGridItem in &WizardData.Pessoas2.Grid
&RanchoAreasEnsinoPessoas = new() &RanchoAreasEnsinoPessoas.locCodigo = &PessoasGridItem.locCodigo &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade = 0
do case case &AreEnsCodigo = 1 &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade = &PessoasGridItem.Bercario1 case &AreEnsCodigo = 2 &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade = &PessoasGridItem.Bercario2 case &AreEnsCodigo = 3 &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade = &PessoasGridItem.Creche case &AreEnsCodigo = 4 &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade = &PessoasGridItem.Emeb case &AreEnsCodigo = 5 &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade = &PessoasGridItem.Integral case &AreEnsCodigo = 99999997 &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade = &PessoasGridItem.Funcionarios endcase
if &RanchoAreasEnsinoPessoas.RanchoAreasEnsinoPessoasQuantidade > 0 &RanchoAreasEnsino.Pessoas.Add(&RanchoAreasEnsinoPessoas) endif
endfor
/* Valor das Per Captas por produto */ for &PerCaptaGridItem in &WizardData.PerCapta2.Grid
&RanchoAreasEnsinoPerCapta = new() &RanchoAreasEnsinoPerCapta.prodCodigo = &PerCaptaGridItem.prodCodigo
do case case &AreEnsCodigo = 1 &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaValor = &PerCaptaGridItem.Bercario1PerCapta &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaOferta = &PerCaptaGridItem.Bercario1Oferta case &AreEnsCodigo = 2 &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaValor = &PerCaptaGridItem.Bercario2PerCapta &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaOferta = &PerCaptaGridItem.Bercario2Oferta case &AreEnsCodigo = 3 &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaValor = &PerCaptaGridItem.CrechePerCapta &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaOferta = &PerCaptaGridItem.CrecheOferta case &AreEnsCodigo = 4 &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaValor = &PerCaptaGridItem.EmebPerCapta &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaOferta = &PerCaptaGridItem.EmebOferta case &AreEnsCodigo = 5 &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaValor = &PerCaptaGridItem.IntegralPerCapta &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaOferta = &PerCaptaGridItem.IntegralOferta case &AreEnsCodigo = 99999997 &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaValor = &PerCaptaGridItem.FuncionarioPerCapta &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaOferta = &PerCaptaGridItem.FuncionarioOferta endcase
if &RanchoAreasEnsinoPerCapta.RanchoAreasEnsinoPerCaptaValor > 0 &RanchoAreasEnsino.PerCapta.Add(&RanchoAreasEnsinoPerCapta) endif
endfor
&Rancho.AreasEnsino.Add(&RanchoAreasEnsino)
Endsub
